import base64,gzip,json,hashlib,pathlib
BASE_SHA='d522959ea955ef788af1df00dfff2dd30bd8566fcbb728823ed39de542d19535'
OUT_SHA='08bb8807b2aa2e3cf416cc8ff417ebbb245bde3128cffe4faf2b7349d82fc8db'
PAYLOAD=''''''
def apply_delta(base_path,out_path):
    b=pathlib.Path(base_path).read_bytes()
    if hashlib.sha256(b).hexdigest()!=BASE_SHA: raise SystemExit('baseline SHA mismatch')
    lines=b.decode('utf-8').splitlines(keepends=True)
    ops=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    out=[]; pos=0
    for i1,i2,repl in ops:
        out.extend(lines[pos:i1]); out.append(repl); pos=i2
    out.extend(lines[pos:])
    data=''.join(out).encode('utf-8')
    if hashlib.sha256(data).hexdigest()!=OUT_SHA: raise SystemExit('patched SHA mismatch')
    pathlib.Path(out_path).write_bytes(data)
if __name__=='__main__': apply_delta('main.cpp','main.cpp')
